@import url('https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* adidas DNA — stark black on white, squared everything, underline energy, three stripes discipline */
.theme-adidas-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.950 0.004 236.5);
  --surface-2: oklch(0.923 0.006 239.8);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.566 0.002 286.4);
  --accent: oklch(0.000 0 0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.566 0.002 286.4);
  --line: oklch(0.000 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.568 0.200 26.4);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: none;
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 2px oklch(0 0 0);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Barlow", "Helvetica Neue", sans-serif;
  --font-body: "Barlow", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-adidas-dna h1,
.theme-adidas-dna h2,
.theme-adidas-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-adidas-dna { --font-ui: var(--font-display); background-image: repeating-linear-gradient(-60deg, oklch(0 0 0 / 3%) 0 14px, transparent 14px 42px); background-size: 300px 300px; background-repeat: no-repeat; background-position: top right; }
.theme-adidas-dna h1, .theme-adidas-dna h2 { text-transform: uppercase; letter-spacing: -0.01em; }
.theme-adidas-dna button { text-transform: uppercase; letter-spacing: 0.12em; }
.theme-adidas-dna button:hover { text-decoration: underline; text-underline-offset: 4px; }

/* depth */
.theme-adidas-dna ::selection { background: oklch(0 0 0); color: oklch(1 0 0); }
.theme-adidas-dna h2 { border-left: 12px solid; border-image: repeating-linear-gradient(180deg, var(--fg) 0 25%, transparent 25% 37.5%, var(--fg) 37.5% 62.5%, transparent 62.5% 75%, var(--fg) 75% 100%) 1; padding-left: 0.5em; }
.theme-adidas-dna thead th { text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.85em; border-bottom: 3px solid var(--fg); background: transparent; }
.theme-adidas-dna td { border-bottom: 1px solid oklch(0 0 0 / 15%); }
.theme-adidas-dna tbody tr:hover { background: var(--surface); box-shadow: inset 3px 0 0 var(--fg); }
.theme-adidas-dna a { color: var(--fg); text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 4px; }
.theme-adidas-dna a:hover { text-decoration-thickness: 4px; }
.theme-adidas-dna input, .theme-adidas-dna select, .theme-adidas-dna textarea { border: 1px solid var(--fg); border-radius: 0; background: var(--bg); }
.theme-adidas-dna input:focus-visible, .theme-adidas-dna select:focus-visible, .theme-adidas-dna textarea:focus-visible { outline: none; border-color: var(--fg); box-shadow: 3px 3px 0 var(--fg); }
.theme-adidas-dna kbd { border: 1px solid var(--fg); border-radius: 0; box-shadow: 2px 2px 0 var(--fg); padding: 0.1em 0.45em; background: var(--bg); }
.theme-adidas-dna .label-caps { border-bottom: 2px solid var(--fg); padding-bottom: 2px; }
.theme-adidas-dna .themed-border { border: 1px solid var(--fg); box-shadow: 4px 4px 0 var(--fg); }
.theme-adidas-dna button:active { transform: translate(2px, 2px); }
.theme-adidas-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-adidas-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-adidas-dna ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; }

/* alt mode: black away kit — pure white on pure black, stripes in white */
.theme-adidas-dna.alt-mode {
  --bg: oklch(0.000 0 0);
  --surface: oklch(0.150 0.000 0.0);
  --surface-2: oklch(0.220 0.000 0.0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.720 0.002 286.4);
  --line: oklch(1.000 0 0);
  --shadow-1: none;
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(1.000 0 0);
  --accent-fg: oklch(0.000 0 0);
  --glow: 0 0 0 2px oklch(1 0 0);
  background-image: repeating-linear-gradient(-60deg, oklch(1 0 0 / 4%) 0 14px, transparent 14px 42px);
  background-size: 300px 300px;
  background-repeat: no-repeat;
  background-position: top right;
}
.theme-adidas-dna.alt-mode ::selection { background: oklch(1 0 0); color: oklch(0 0 0); }
.theme-adidas-dna.alt-mode td { border-bottom-color: oklch(1 0 0 / 20%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
